import random,math,json,collections

def tail(xs):
 xs=[x for x in xs if x]; d=collections.Counter({0:1})
 for x in xs:
  e=collections.Counter()
  for s,n in d.items():e[s+x]+=n;e[s-x]+=n
  d=e
 return sum(n for s,n in d.items() if s>=sum(xs))/(2**len(xs))
def pairtail(xs):
 n=sum(x!=0 for x in xs);positive=sum(x>0 for x in xs);return sum(math.comb(n,i) for i in range(positive,n+1))/(2**n)
def wilson(k,n):
 z=1.959963984540054;p=k/n;d=1+z*z/n;center=(p+z*z/(2*n))/d;w=z*math.sqrt(p*(1-p)/n+z*z/(4*n*n))/d;return [center-w,center+w]
def run(scenario,dose):
 rng=random.Random(20261127000+int(dose*1000)+(100 if scenario=='one_table' else 0));n=720; reject=[0,0,0];nonzero=collections.Counter(); planted=0
 for rep in range(n):
  sums=[];pairs=[]
  for b in range(6):
   orient=rng.randrange(2)
   for fol in range(2):
    diffs=[]
    if scenario=='one_table':
     # Common page-local weights generate body; two unlabeled candidate streams
     # sampled symmetrically. Distinct candidate words and fillers have equal length.
     pop=list(range(120));weights=[rng.expovariate(1) for _ in pop];body=rng.choices(pop,weights,k=50);candidates=rng.sample(pop,24); left=candidates[:12];right=candidates[12:];labels,shams=(left,right) if orient else (right,left)
     fillers=[i for i,w in enumerate(body) if w not in candidates]
     for word in labels:
      if word not in body and rng.random()<dose and fillers:
       body[fillers.pop()]=word;planted+=1
     present=set(body)
     diffs=[int(a in present)-int(c in present) for a,c in zip(labels,shams)]
    else:
     for j in range(12):
      left=int(rng.random()<.52);right=int(rng.random()<.12);l,r=(left,right) if orient else (right,left)
      if not l and rng.random()<dose:l=1;planted+=1
      diffs.append(l-r)
    sums.append(sum(diffs));pairs.extend(diffs)
  block=[sums[i]+sums[i+1] for i in range(0,12,2)];nonzero[sum(x!=0 for x in block)]+=1
  for i,p in enumerate((tail(block),tail(sums),pairtail(pairs))):reject[i]+=p<=.05
 return {'rejections':reject,'wilson':[wilson(k,n) for k in reject],'nonzero_blocks':dict(nonzero),'attained_insertions':planted}
out={s:{str(d):run(s,d) for d in (0,.1,.25,.5)} for s in ('shared_bias','one_table')};print(json.dumps(out,indent=2))
